export function initCustomerAccount({billing,toast=()=>{},onOpenOrder=async()=>{}}){
 const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('./customer-account.css',import.meta.url).href;document.head.append(style);
 const trigger=document.createElement('button');trigger.type='button';trigger.className='header-library-button customer-account-trigger';trigger.textContent='Minha conta';document.querySelector('.announcement').append(trigger);const accountActions=document.createElement('nav');accountActions.className='customer-account-actions';accountActions.setAttribute('aria-label','Seus presentes e sua conta');for(const button of document.querySelectorAll('.announcement .header-library-button'))accountActions.append(button);document.querySelector('.announcement').append(accountActions);
 const dialog=document.createElement('dialog');dialog.className='customer-account-dialog';dialog.setAttribute('aria-labelledby','customer-account-title');dialog.innerHTML='<header><h2 id="customer-account-title">Minha conta</h2><button type="button" class="account-close" aria-label="Fechar minha conta">Fechar</button></header><section class="account-email-step"><p>Entre com seu e-mail para acessar as compras vinculadas à sua conta. Não precisa criar uma senha.</p><form class="account-email-form"><label for="account-email">Seu e-mail<input id="account-email" type="email" autocomplete="email" inputmode="email" maxlength="254" required placeholder="voce@exemplo.com"></label><button class="button primary" type="submit">Receber código de acesso</button></form></section><section class="account-code-step" hidden><p>Digite o código enviado para <strong class="account-code-email"></strong>. Confira também o spam.</p><form class="account-code-form"><label for="account-code">Código de 8 dígitos<input id="account-code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="16" required aria-describedby="account-code-help"></label><small id="account-code-help">Você pode colar o código inteiro. Ele só pode ser usado uma vez.</small><button class="button primary" type="submit">Entrar na minha conta</button></form><div class="account-code-actions"><button type="button" class="account-resend">Reenviar código</button><button type="button" class="account-change-email">Usar outro e-mail</button></div></section><section class="account-home" hidden><p class="account-identity"></p><p>Seus presentes publicados podem ser abertos em outro aparelho. Rascunhos ainda não publicados ficam no navegador onde você os criou.</p><button type="button" class="account-claim" hidden>Vincular minhas compras deste aparelho</button><p class="account-claim-note" hidden>A vinculação usa as chaves das compras salvas neste aparelho. Informar um e-mail não transfere compras de outra pessoa.</p><div class="account-orders" aria-label="Minhas compras"></div><button type="button" class="account-refresh">Atualizar minhas compras</button><button type="button" class="account-logout">Sair da conta</button></section><p class="account-status" role="status" aria-live="polite"></p><small class="account-help">Perdeu uma compra antiga e não tem o arquivo de acesso? <a href="mailto:bacochinakawai@gmail.com">Fale com o atendimento</a>. Não envie senhas ou códigos por mensagem.</small>';document.body.append(dialog);
 const $=s=>dialog.querySelector(s),status=$('.account-status');let account=null,step='email',challengeId='',email='',busy=false,resendAt=0,timer=null,interaction=0,handoff=false;
 function cooldown(){const seconds=Math.max(0,Math.ceil((resendAt-Date.now())/1000));$('.account-resend').disabled=busy||seconds>0;$('.account-resend').textContent=seconds?'Reenviar em '+seconds+' s':'Reenviar código';if(!seconds&&timer){clearInterval(timer);timer=null;}}
 function setBusy(value){busy=value;dialog.setAttribute('aria-busy',String(value));for(const button of dialog.querySelectorAll('button:not(.account-close)'))button.disabled=value;cooldown();}
 function render(){const logged=account?.authenticated===true;$('.account-email-step').hidden=logged||step!=='email';$('.account-code-step').hidden=logged||step!=='code';$('.account-home').hidden=!logged;trigger.textContent='Minha conta';$('.account-code-email').textContent=email;$('.account-identity').textContent=logged?'Você entrou como '+account.email:'';const list=$('.account-orders');list.replaceChildren();$('.account-claim').hidden=true;$('.account-claim-note').hidden=true;if(!logged)return;
  const rows=billing.list().filter(r=>r.sessionAuth);if(!rows.length){const p=document.createElement('p');p.textContent='Você ainda não tem compras vinculadas a esta conta.';list.append(p);}for(const item of rows){const row=document.createElement('article'),title=document.createElement('strong'),note=document.createElement('p'),button=document.createElement('button'),metadata=billing.get(item.id)||item,format=metadata.delivery?.format||metadata.requestedFormat,kind=({cartao:'Cartão',livro:'Livro',convite:'Convite',stories:'Stories'})[format]||billing.config.plans?.[item.planId]?.title||'Presente',recipient=metadata.delivery?.recipient||metadata.recipient,date=Number.isFinite(metadata.createdAt)&&metadata.createdAt>0?new Date(metadata.createdAt).toLocaleDateString('pt-BR'):'';row.dataset.orderId=item.id;title.textContent=recipient?kind+' para '+recipient:date?kind+' · '+date:kind;note.textContent=item.expired?'Período de acesso encerrado':item.status==='approved'?(item.delivery?'Publicado · pronto para abrir':'Compra confirmada · ainda não publicado'):item.status==='revoked'?'Compra cancelada ou reembolsada':item.status==='failed'?'Pagamento não aprovado':'Pagamento ainda não confirmado';button.type='button';button.textContent=item.expired?'Ver orientação':item.status==='approved'?(item.delivery?'Abrir para editar':'Continuar criando'):'Ver situação da compra';button.addEventListener('click',async()=>{if(busy)return;const own=interaction;setBusy(true);status.textContent='Conferindo esta compra…';try{let record=billing.get(item.id)||item;if(!record.expired)record=await billing.refresh(record,record.status!=='approved')||record;if(own!==interaction||!dialog.open)return;const expired=record.expired===true||(Number.isFinite(record.expiresAt)&&record.expiresAt*1000<=Date.now());render();if(expired){status.textContent='O período de acesso de 365 dias desta compra terminou. A cópia que você baixou continua com você. Para criar outro presente, escolha um novo plano; seu rascunho atual não foi apagado.';return;}if(record.status==='revoked'){status.textContent='Esta compra foi cancelada ou reembolsada. Seu rascunho foi preservado. Se precisar de ajuda, fale com bacochinakawai@gmail.com.';return;}if(record.status!=='approved'){status.textContent=record.status==='failed'?'O pagamento não foi aprovado. Para ajuda com esta compra, fale com bacochinakawai@gmail.com. Seu rascunho foi preservado.':'O pagamento ainda não foi confirmado. Se você já pagou, aguarde alguns instantes e toque em “Ver situação da compra” novamente. Seu rascunho continua aqui.';return;}handoff=true;dialog.close();if(await onOpenOrder(record)===false&&own===interaction&&!document.querySelector('dialog[open]')){dialog.showModal();status.textContent='Abertura cancelada. Seu rascunho atual foi preservado.';}}catch{if(own!==interaction||!dialog.open&&!handoff||!dialog.open&&document.querySelector('dialog[open]'))return;if(!dialog.open)dialog.showModal();status.textContent='Não foi possível conferir esta compra agora. Confira a conexão e tente novamente.';}finally{handoff=false;setBusy(false);}});row.append(title,note,button);list.append(row);}
  const canClaim=billing.list().some(r=>!r.sessionAuth&&r.id&&!billing.get(r.id)?.isAdmin);$('.account-claim').hidden=!canClaim;$('.account-claim-note').hidden=!canClaim;
 }
 async function api(path,body){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);let response;try{response=await fetch('/api/customer/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:controller.signal});}catch{throw Error('Não foi possível conectar agora. Confira sua conexão e tente novamente.');}finally{clearTimeout(timeout);}const data=await response.json().catch(()=>({}));if(!response.ok){const error=Error(response.status===429?'Muitas tentativas. Aguarde um pouco antes de tentar novamente.':path==='verify-code'?'Não foi possível validar esse código. Confira os 8 dígitos ou peça outro código.':'Não foi possível concluir agora. Confira sua conexão e tente novamente.');error.status=response.status;throw error;}return data;}
 async function loadAccount(){const session=await billing.syncAccount();account=session?.authenticated?session:null;if(!account){billing.clearAccount();step=challengeId?'code':'email';}render();return account;}
 async function sendCode(){const data=await api('request-code',{email});if(typeof data.challengeId!=='string'||!data.challengeId)throw Error('Não foi possível preparar o acesso. Tente novamente.');challengeId=data.challengeId;step='code';$('.account-code-form').reset();resendAt=Date.now()+60000;if(timer)clearInterval(timer);timer=setInterval(cooldown,1000);render();cooldown();status.textContent='Código solicitado. Abra seu e-mail e digite os 8 dígitos aqui.';$('#account-code').focus();}
 $('.account-email-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||!event.currentTarget.reportValidity())return;email=$('#account-email').value.trim();setBusy(true);status.textContent='Preparando seu código…';try{await sendCode();}catch(error){status.textContent=error.message||'Não foi possível enviar o código agora.';}finally{setBusy(false);}});
 $('.account-code-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const code=$('#account-code').value.replace(/\s/g,'');if(!/^\d{8}$/.test(code)){status.textContent='Digite os 8 dígitos do código recebido por e-mail.';$('#account-code').focus();return;}setBusy(true);status.textContent='Conferindo seu código…';try{await api('verify-code',{challengeId,code});challengeId='';$('#account-code').value='';await loadAccount();if(!account)throw Error('Sua sessão não pôde ser confirmada. Solicite outro código.');step='home';render();status.textContent='Você entrou. Novas compras feitas nesta sessão ficam vinculadas à sua conta.';$('.account-identity').tabIndex=-1;$('.account-identity').focus();}catch(error){status.textContent=error.status?error.message:'Não foi possível concluir o acesso. Confira a conexão e solicite outro código se necessário.';}finally{setBusy(false);}});
 $('.account-resend').addEventListener('click',async()=>{if(busy||Date.now()<resendAt)return;setBusy(true);status.textContent='Solicitando outro código…';try{await sendCode();}catch(error){status.textContent=error.message;}finally{setBusy(false);}});
 $('.account-change-email').addEventListener('click',()=>{if(busy)return;challengeId='';step='email';$('.account-code-form').reset();status.textContent='';render();$('#account-email').focus();});
 $('.account-claim').addEventListener('click',async()=>{if(busy)return;setBusy(true);status.textContent='Conferindo as chaves das compras deste aparelho…';try{const result=await billing.claimLocalPurchases();await loadAccount();status.textContent=result.failed?'Vinculação concluída para '+result.claimed+' compra(s). Algumas compras não puderam ser vinculadas; seus arquivos de acesso continuam válidos.':result.claimed+' compra(s) vinculada(s) à sua conta.';}catch{status.textContent='Não foi possível vincular as compras agora. Seus arquivos de acesso continuam disponíveis; tente novamente.';}finally{setBusy(false);}});
 $('.account-refresh').addEventListener('click',async()=>{if(busy)return;setBusy(true);status.textContent='Atualizando suas compras…';try{await loadAccount();status.textContent=account?'Lista atualizada.':'Sua sessão terminou. Entre novamente com seu e-mail.';}catch{status.textContent='Não foi possível atualizar. Confira sua conexão e tente novamente.';}finally{setBusy(false);}});
 $('.account-logout').addEventListener('click',async()=>{if(busy)return;setBusy(true);try{await api('logout',{});billing.clearAccount({forgetLinked:true});account=null;step='email';email='';challengeId='';$('.account-email-form').reset();$('.account-code-form').reset();render();status.textContent='Você saiu da conta. Os rascunhos deste navegador continuam aqui.';toast('Você saiu da conta.');}catch{status.textContent='Não foi possível confirmar a saída. Confira a conexão e tente novamente.';}finally{setBusy(false);}});
 trigger.addEventListener('click',async()=>{if(dialog.open)return;const own=++interaction;status.textContent='';render();dialog.showModal();await billing.ready;if(own!==interaction||!dialog.open)return;const origin=billing.config.customerAccountOrigin;if(origin&&origin!==location.origin){$('.account-email-step').hidden=true;$('.account-code-step').hidden=true;$('.account-home').hidden=true;status.replaceChildren(document.createTextNode('Sua conta fica no domínio principal. Os rascunhos e arquivos de acesso deste endereço continuam neste navegador. '));const link=document.createElement('a');link.href=origin;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Abrir o Capimimo e entrar em Minha conta';link.style.textDecoration='underline';status.append(link);return;}if(busy)return;setBusy(true);try{await loadAccount();}catch{if(own!==interaction||!dialog.open)return;account=null;billing.clearAccount();step=challengeId?'code':'email';render();status.textContent='Não foi possível conferir sua sessão. Tente novamente em instantes.';}finally{setBusy(false);}});
 $('.account-close').addEventListener('click',()=>{interaction++;dialog.close();});dialog.addEventListener('cancel',()=>{interaction++;});dialog.addEventListener('close',()=>{if(!dialog.open&&!handoff)interaction++;});document.addEventListener('billing:change',()=>{if(account?.authenticated){if(billing.account?.authenticated===false){account=null;step='email';}render();setBusy(busy);}});addEventListener('pagehide',()=>{if(timer)clearInterval(timer);},{once:true});return{open:()=>trigger.click()};
}
